// Blur TOP -- GPU convolution blur
uniform float u_size;uniform int u_quality;uniform bool u_rotate;
in vec2 v_uv;out vec4 fragColor;
vec4 gs(sampler2D tex,vec2 uv,vec2 off){vec4 c=vec4(0);float t=0;int r=u_quality;for(int x=-r;x<=r;x++)for(int y=-r;y<=r;y++){float w=exp(-float(x*x+y*y)/(2.*u_size*u_size));c+=texture(tex,uv+vec2(x,y)*off)*w;t+=w;}return c/t;}
void main(){vec2 off=u_rotate?vec2(0,dFdy(v_uv.y)):vec2(dFdx(v_uv.x),dFdy(v_uv.y));fragColor=gs(sTD2DInputs[0],v_uv,off*u_size*.001);}

