fn gs(uv:vec2f,off:vec2f)->vec4f{var c=vec4f(0);var t=0.;let r=u_quality;for(var x=-r;x<=r;x++)for(var y=-r;y<=r;y++){let w=exp(-f32(x*x+y*y)/(2.*u_size*u_size));c+=textureSample(inputTex,ts,uv+vec2f(f32(x),f32(y))*off)*w;t+=w;}return c/t;}
fn frag(v_uv:vec2f)->vec4f{return gs(v_uv,vec2f(ddx(v_uv.x),ddy(v_uv.y))*u_size*.001);}

