// Edge TOP -- Sobel
uniform float u_strength;uniform float u_threshold;
in vec2 v_uv;out vec4 fragColor;
void main(){vec2 o=vec2(dFdx(v_uv.x),dFdy(v_uv.y));
vec4 c00=texture(sTD2DInputs[0],v_uv+vec2(-o.x,-o.y)),c10=texture(sTD2DInputs[0],v_uv+vec2(0,-o.y)),c20=texture(sTD2DInputs[0],v_uv+vec2(o.x,-o.y));
vec4 c01=texture(sTD2DInputs[0],v_uv+vec2(-o.x,0)),c21=texture(sTD2DInputs[0],v_uv+vec2(o.x,0));
vec4 c02=texture(sTD2DInputs[0],v_uv+vec2(-o.x,o.y)),c12=texture(sTD2DInputs[0],v_uv+vec2(0,o.y)),c22=texture(sTD2DInputs[0],v_uv+vec2(o.x,o.y));
vec4 gx=(c20+2*c21+c22)-(c00+2*c01+c02),gy=(c02+2*c12+c22)-(c00+2*c10+c20);
