shaders.glsl:
// HSV Adjust TOP
uniform vec3 u_hsvOffset;uniform vec3 u_hsvMultiply;
in vec2 v_uv;out vec4 fragColor;
vec3 h2r(vec3 c){vec4 K=vec4(1,2./3.,1./3.,3);vec3 p=abs(fract(c.xxx+K.xyz)*6-K.www);return c.z*mix(K.xxx,clamp(p-K.xxx,0,1),c.y);}
vec3 r2h(vec3 c){vec4 K=vec4(0,-1./3.,2./3.,-1);vec4 p=c.g<c.b?vec4(c.bg,K.wz):vec4(c.gb,K.xy);vec4 q=c.r<p.x?vec4(p.xyw,c.r):vec4(c.r,p.yzx);
float d=q.x-min(q.w,q.y),e=1e-10;return vec3(abs(q.z+(q.w-q.y)/(6*d+e)),d/(q.x+e),q.x);}
void main(){vec4 c=texture(sTD2DInputs[0],v_uv);vec3 h=r2h(c.rgb);h=(h+u_hsvOffset)*u_hsvMultiply;h=clamp(fract(h),0,1);fragColor=vec4(h2r(h),c.a);}

