// HSV Adjust TOP -- WebGPU
@group(1)@binding(0)var u_res:vec4f;@group(1)@binding(1)var u_hsvOffset:vec3f;@group(1)@binding(2)var u_hsvMultiply:vec3f;
@group(2)@binding(0)var inputTex:texture_2d<f32>;
fn r2h(c:vec3f)->vec3f{let v=max(max(c.r,c.g),c.b);let d=v-min(min(c.r,c.g),c.b);var h:f32;if(d<.0001){h=0;}else if(v==c.r){h=(c.g-c.b)/d;}else if(v==c.g){h=2+(c.b-c.r)/d;}else{h=4+(c.r-c.g)/d;}h=h/6;if(h<0){h+=1;}return vec3f(h,v>0?d/v:0,v);}
fn h2r(c:vec3f)->vec3f{let h=c.x*6;let s=c.y;let v=c.z;let i=floor(h);let f=h-i;let p=v*(1-s);let q=v*(1-f*s);let t=v*(1-(1-f)*s);if(i==0){return vec3f(v,t,p);}if(i==1){return vec3f(q,v,p);}if(i==2){return vec3f(p,v,t);}if(i==3){return vec3f(p,q,v);}if(i==4){return vec3f(t,p,v);}return vec3f(v,p,q);}
fn frag(v_uv:vec2f)->vec4f{let c=textureSample(inputTex,ts,v_uv);var h=r2h(c.rgb);h=(h+u_hsvOffset)*u_hsvMultiply;h=clamp(fract(h),vec3f(0),vec3f(1));return vec4f(h2r(h),c.a);}

